// The read schema the active deployment was built against. Every deployment pins its schema hash
// (`CHAIN.readSchema`, db/prepare-chain-deployment.mjs), so an older deployment that is still
// live keeps reading its own events and storage while `generated/` moves to the current audit.
// Frozen sets under `schemas/` are copies of an earlier `generated/`; never regenerate them.
import * as current from './generated/index.js';
import * as beforeLoans from './schemas/eb3907da/index.js';
import * as beforeVaultAllocations from './schemas/a357e43b/index.js';
import * as beforeLiquidationSteth from './schemas/7c1c6249/index.js';
import * as beforeAfkingSections from './schemas/3a7cd786/index.js';
import * as beforeMineFlipMultiplier from './schemas/0b2b1181/index.js';
import * as run56 from './schemas/224de529/index.js';
import * as beforeRecycling from './schemas/32c604531/index.js';
import * as beforeHeaderTail from './schemas/b551af32/index.js';
import * as beforeStableOwners from './schemas/8b05afd9/index.js';
import * as beforeWholeTokens from './schemas/d0e3665a/index.js';
import * as beforeDecimatorJackpot from './schemas/54fe7634/index.js';
import * as beforeWalletIds from './schemas/5cd4b457/index.js';
import * as beforeBafCandidates from './schemas/f2677649/index.js';
import { CHAIN } from '../app/chain-config.js';

export const BEFORE_BAF_CANDIDATES_SCHEMA_HASH = beforeBafCandidates.SCHEMA_HASH;
export const BEFORE_MINE_FLIP_MULTIPLIER_SCHEMA_HASH = beforeMineFlipMultiplier.SCHEMA_HASH;
export const BEFORE_AFKING_SECTIONS_SCHEMA_HASH = beforeAfkingSections.SCHEMA_HASH;
export const BEFORE_LIQUIDATION_STETH_SCHEMA_HASH = beforeLiquidationSteth.SCHEMA_HASH;
export const BEFORE_VAULT_ALLOCATIONS_SCHEMA_HASH = beforeVaultAllocations.SCHEMA_HASH;
export const BEFORE_LOANS_SCHEMA_HASH = beforeLoans.SCHEMA_HASH;
export function hasAccountLoans() { return active === current; }
/** Run 72 draws the shared lootbox EV allowance at opening; queued words reserve that lane. */
export function hasOpeningLootboxEv() { return active === current; }
/**
 * Audit 4f4aa8377: 85-bit queued box entries, three per word, with the compact order layout.
 * Earlier wallet-ID deployments (runs 66-74) stored one entry per word in the counted-order layout.
 */
export function hasCompactBoxQueue() { return active === current; }
const SETS = [beforeLoans, beforeVaultAllocations, beforeLiquidationSteth, beforeAfkingSections, beforeMineFlipMultiplier, beforeBafCandidates, current, run56, beforeRecycling, beforeHeaderTail, beforeStableOwners, beforeWholeTokens, beforeDecimatorJackpot, beforeWalletIds];
let active = SETS.find((set) => set.SCHEMA_HASH === CHAIN?.readSchema) ?? current;

/** The run-56 contracts (audit 224de529): CoinDrawBattle, bonus trait draws, drawKind foil claims. */
export const RUN56_SCHEMA_HASH = run56.SCHEMA_HASH;
export const CURRENT_SCHEMA_HASH = current.SCHEMA_HASH;
export const BEFORE_STABLE_OWNERS_SCHEMA_HASH = beforeStableOwners.SCHEMA_HASH;
export const BEFORE_RECYCLING_SCHEMA_HASH = beforeRecycling.SCHEMA_HASH;
export const BEFORE_HEADER_TAIL_SCHEMA_HASH = beforeHeaderTail.SCHEMA_HASH;
/** Run 63 (audit 95d88f68b): the last contracts with 18-decimal FLIP and WWXRP. */
export const BEFORE_WHOLE_TOKENS_SCHEMA_HASH = beforeWholeTokens.SCHEMA_HASH;
/**
 * Run 64 (audit ca2bb497f): whole-token FLIP, but the last contracts with the per-entry Decimator
 * coin, day-keyed sDGNRS redemptions and the fixed 8,000-FLIP craps jackpot fee.
 */
export const BEFORE_DECIMATOR_JACKPOT_SCHEMA_HASH = beforeDecimatorJackpot.SCHEMA_HASH;
/**
 * Run 65 (audit 12daf8060): the last contracts keyed by wallet ADDRESS, with 18-decimal DGNRS/sDGNRS,
 * address-keyed events, salvage, parimutuel claims and the plain-symbol Degenerette reels.
 */
export const BEFORE_WALLET_IDS_SCHEMA_HASH = beforeWalletIds.SCHEMA_HASH;

// Audit b05ea7c50 (run 64) made FLIP and WWXRP zero-decimal tokens. Every earlier set here used
// 18 decimals; a set frozen from now on keeps whole tokens, so only these five are listed.
const EIGHTEEN_DECIMAL_TOKEN_SETS = new Set([run56, beforeRecycling, beforeHeaderTail, beforeStableOwners, beforeWholeTokens]);
// Every set before audit 12daf8060 (run 65); see the three feature checks below.
const BEFORE_RUN65_SETS = new Set([...EIGHTEEN_DECIMAL_TOKEN_SETS, beforeDecimatorJackpot]);
// Every set before audit 98cd2a781 (run 66); see hasWalletIds() below.
const BEFORE_RUN66_SETS = new Set([...BEFORE_RUN65_SETS, beforeWalletIds]);

/** Run 68 adds a uint32 gas-estimate multiplier; zero selects its default. */
export function hasMineFlipMultiplier() { return active === current || active === beforeLoans || active === beforeVaultAllocations || active === beforeLiquidationSteth || active === beforeAfkingSections; }
export function activeSchemaHash() { return active.SCHEMA_HASH; }
/** True when the active deployment's FLIP and WWXRP have zero decimals (one raw unit = one token). */
export function hasWholeTokens() { return !EIGHTEEN_DECIMAL_TOKEN_SETS.has(active); }
/**
 * Audit 12daf8060: exactly min(1000, ceil(T/2)) of the T = N + M Decimator entries survive by
 * rotated stratified sampling (DecimatorSamplingLib); the per-entry final coin is gone. Round word 0
 * repacked (uint96 pool | uint40 count | uint64 credited total), places go up to 200, an x5 round
 * can add jackpot-generated entries N+1..N+M, and the minimum burn is 2,000 FLIP.
 */
export function hasDecimatorSurvivorSampling() { return !BEFORE_RUN65_SETS.has(active); }
/** Audit 01f11477c: sDGNRS gambling burns join uint32 redemption batches (day/period keys before). */
export function hasRedemptionBatches() { return !BEFORE_RUN65_SETS.has(active); }
/** Audit bcdba75a9: the daily craps jackpot fee is 6,000 / 8,000 / 10,000 FLIP (a fixed 8,000 before). */
export function hasVariableJackpotPrice() { return !BEFORE_RUN65_SETS.has(active); }
/**
 * Audit 98cd2a781 (run 66): every wallet has a permanent uint32 ID (Game `walletIdOf`, mintPacked
 * bits 224-255, `WalletRegistered(id, owner)`). Player entry points take the ID first (0 = caller),
 * most events and storage maps carry/are keyed by the ID, DGNRS/sDGNRS have 12 decimals, lootbox
 * custom sizes and Degenerette ETH stakes are whole gwei, and Degenerette reels carry wild colors.
 */
export function hasWalletIds() { return !BEFORE_RUN66_SETS.has(active); }
/** Audit 98cd2a781: DGNRS and sDGNRS use 12 decimals (18 before). */
export function hasTwelveDecimalDgnrs() { return !BEFORE_RUN66_SETS.has(active); }
/** Audit f9ac5160c (run 66): Degenerette wild-color reels (score 1..9, `score | wilds << 4` tail). */
export function hasDegeneretteWilds() { return !BEFORE_RUN66_SETS.has(active); }
export function loadSchema(name) { return active.loadSchema(name); }
/** True while the site reads a run-56 deployment. */
export function isRun56Schema() { return active === run56; }
/**
 * Where the jackpot battle's events are read under the active schema: run 56's standalone
 * CoinDrawBattle, or CRAPS from audit 0889affc1 on (JackpotBattle is CrapsBattle's delegatecall
 * module, so its calls and events are all at the CRAPS address; JACKPOT_BATTLE emits nothing).
 */
export function jackpotBattleKey() { return active === run56 ? 'COIN_DRAW_BATTLE' : 'CRAPS'; }

/** Tests (and the fixture client) pick a schema by hash; returns the previous hash. */
export function useSchema(hash) {
  const previous = active.SCHEMA_HASH;
  const next = SETS.find((set) => set.SCHEMA_HASH === hash);
  if (!next) throw new Error(`Unknown read schema ${hash}`);
  active = next;
  return previous;
}

/** Feature detection keeps historical deployments on their actual event surface. */
export async function hasHottestShooterPrize() {
  return (await loadSchema('CRAPS')).abi.some(fragment => fragment.type === 'event' && fragment.name === 'CrapsHottestShooterPaid');
}
/** Audit 95d88f68b: main-daily ticket awards can land straight in the live L+1 buffer as batches. */
export async function hasTicketBatches() {
  return (await loadSchema('GAME')).abi.some(fragment => fragment.type === 'event' && fragment.name === 'JackpotTicketBatchWin');
}
